vars_= ['lbg','lmk','sep','rbg','rmk']
def feats(v):
    lbg,lmk,sep,rbg,rmk=v
    base={'lbg':lbg,'lmk':lmk,'sep':sep,'rbg':rbg,'rmk':rmk}
    f=dict(base)
    for k,val in base.items():
        f[k+'//2']=val//2; f[k+'//3']=val//3; f['('+k+'+1)//2']=(val+1)//2
        f[k+'%5']=val%5; f[k+'%7']=val%7; f[k+'%4']=val%4; f[k+'%3']=val%3
    f['abs(lmk-rmk)']=abs(lmk-rmk); f['abs(lbg-rbg)']=abs(lbg-rbg)
    f['(lmk+rmk)%10']=(lmk+rmk)%10; f['(lbg+rbg)%10']=(lbg+rbg)%10
    f['(lmk+sep)%10']=(lmk+sep)%10; f['(rmk+sep)%10']=(rmk+sep)%10
    f['(lmk-lbg)%10']=(lmk-lbg)%10; f['(lmk-rbg)%10']=(lmk-rbg)%10
    f['(rbg-lbg)%10']=(rbg-lbg)%10; f['(rmk-lbg)%10']=(rmk-lbg)%10
    f['(lmk+rmk+sep)%10']=(lmk+rmk+sep)%10
    f['(lbg+lmk)%10']=(lbg+lmk)%10; f['(rbg+rmk)%10']=(rbg+rmk)%10
    f['(lbg+rmk)%10']=(lbg+rmk)%10; f['(rbg+lmk)%10']=(rbg+lmk)%10
    f['3const']=3; f['2const']=2
    return f
